 V(10,"FA2-10","نقاشی کردن","naqqāshi kardan","to paint; draw","نقاشی کردن","نقاشی کن","نقاشی کردن با رنگ‌های طبیعی تجربه‌ای زیباست.","Naqqāshi kardan bā rang-hā-ye tabi'i tajrobe-i zibāst.","Painting with natural colours is a beautiful experience.","یک منظرهٔ ساده نقاشی کن.","Yek manzare-ye sāde naqqāshi kon.","Paint a simple landscape.");
 N(11,"FA2-11","طناب‌بازی","tanāb-bāzi","skipping rope; rope jumping","اسم — noun","طناب‌بازی یکی از بازی‌های پرتحرک کودکان است.","Tanāb-bāzi yeki az bāzi-hā-ye por-taharruk-e kudakān ast.","Rope skipping is an active children's game.");
 V(11,"FA2-11","آشتی کردن","āshti kardan","to make up; reconcile","آشتی کردن","آشتی کن","آشتی کردن پس از اختلاف به گفتگو نیاز دارد.","Āshti kardan pas az ekhtelāf be goftogu niyāz dārad.","Making up after a disagreement requires conversation.","با دوستت آشتی کن.","Bā dustat āshti kon.","Make up with your friend.");
 N(12,"FA2-12","صرافی","sarrāfi","currency exchange office","اسم — noun","مسافر پیش از سفر به صرافی رفت.","Mosāfer pish az safar be sarrāfi raft.","The traveller went to the currency exchange before the trip.");
 V(12,"FA2-12","شارژ کردن","shārj kardan","to charge (a phone/device)","شارژ کردن","شارژ کن","شارژ کردن تلفن پیش از پرواز مفید است.","Shārj kardan-e telefon pish az parvāz mofid ast.","Charging the phone before a flight is useful.","گوشی‌ات را شارژ کن.","Gushiyat rā shārj kon.","Charge your phone.");
 N(13,"FA2-13","چراغ راهنما","cherāgh-e rāhnamā","turn signal; indicator","گروه اسمی — noun phrase","راننده پیش از پیچیدن چراغ راهنما زد.","Rānande pish az pichidan cherāgh-e rāhnamā zad.","The driver used the indicator before turning.");
 V(13,"FA2-13","کمربند بستن","kamarband bastan","to fasten a seat belt","کمربند بستن","کمربند ببند","کمربند بستن پیش از حرکت ضروری است.","Kamarband bastan pish az harekat zaruri ast.","Fastening a seat belt before moving is essential.","پیش از حرکت، کمربند ببند.","Pish az harekat kamarband beband.","Fasten your seat belt before moving.");
 N(14,"FA2-14","نقص فنی","naqs-e fanni","technical fault","گروه اسمی — noun phrase","نقص فنی پرواز باعث تأخیر شد.","Naqs-e fanni-ye parvāz bā'es-e ta'khir shod.","A technical fault caused the flight delay.");
 V(14,"FA2-14","جا گذاشتن","jā gozāshtan","to leave behind; forget","جا گذاشتن","جا نگذار","جا گذاشتن گذرنامه در خانه مشکل‌ساز است.","Jā gozāshtan-e gozarnāme dar khāne moshkel-sāz ast.","Leaving a passport at home causes problems.","مدارکت را جا نگذار.","Madārekat rā jā nagozār.","Do not leave your documents behind.");
 N(15,"FA2-15","فلفل دلمه‌ای","felfel-e dolme-i","bell pepper","اسم — noun","فلفل دلمه‌ای را خرد کردم.","Felfel-e dolme-i rā khord kardam.","I chopped the bell pepper.");
 V(15,"FA2-15","مصرف کردن","masraf kardan","to consume; use","مصرف کردن","مصرف کن","مصرف کردن سبزیجات تازه برای تغذیهٔ متعادل مفید است.","Masraf kardan-e sabzijāt-e tāze barāye taghziye-ye mota'ādel mofid ast.","Eating fresh vegetables is useful for a balanced diet.","آب کافی مصرف کن.","Āb-e kāfi masraf kon.","Drink enough water.");
 N(16,"FA2-16","سرآشپز","sar-āshpaz","head chef","اسم — noun","سرآشپز مواد اولیه را بررسی کرد.","Sar-āshpaz mavādd-e avvaliye rā barrasi kard.","The head chef checked the ingredients.");
 V(16,"FA2-16","نظرخواهی کردن","nazar-khāhi kardan","to ask for feedback","نظرخواهی کردن","نظرخواهی کن","نظرخواهی کردن از مشتریان کیفیت خدمات را بهتر می‌کند.","Nazar-khāhi kardan az moshtariyān keyfiyat-e khadamāt rā behtar mikonad.","Asking customers for feedback improves service quality.","پس از غذا از مهمانان نظرخواهی کن.","Pas az ghazā az mehmānān nazar-khāhi kon.","Ask the guests for feedback after the meal.");
 N(17,"FA2-17","اتاق رو به دریا","otāq-ru-be-daryā","sea-facing room","گروه اسمی — noun phrase","اتاق رو به دریا منظرهٔ زیبایی دارد.","Otāq-ru-be-daryā manzare-ye zibāyi dārad.","The sea-facing room has a beautiful view.");
 V(17,"FA2-17","شکایت کردن","shekāyat kardan","to complain","شکایت کردن","شکایت کن","شکایت کردن باید با احترام و دلیل روشن همراه باشد.","Shekāyat kardan bāyad bā ehterām va dalil-e rowshan hamrāh bāshad.","A complaint should be respectful and supported by a clear reason.","اگر مشکلی هست، محترمانه شکایت کن.","Agar moshkeli hast, mohtaramāne shekāyat kon.","If there is a problem, complain politely.");
 N(18,"FA2-18","مدرک تحصیلی","madrak-e tahsili","educational qualification","گروه اسمی — noun phrase","مدرک تحصیلی او کارشناسی ارشد است.","Madrak-e tahsili-ye u kārshenāsi-ye arshad ast.","His educational qualification is a master's degree.");
 V(18,"FA2-18","پرداخت کردن","pardākht kardan","to pay","پرداخت کردن","پرداخت کن","پرداخت کردن شهریه باید در زمان مقرر انجام شود.","Pardākht kardan-e shahriye bāyad dar zamān-e moqarrar anjām shavad.","Tuition must be paid by the due date.","شهریه را به‌موقع پرداخت کن.","Shahriye rā be-mowqe' pardākht kon.","Pay the tuition on time.");
 N(19,"FA2-19","لوازم‌التحریر","lavāzem-ot-tahrir","stationery","اسم — noun","لوازم‌التحریر را از فروشگاه خریدم.","Lavāzem-ot-tahrir rā az forushgāh kharidam.","I bought stationery from the shop.");
 V(19,"FA2-19","خرید کردن","kharid kardan","to shop; make a purchase","خرید کردن","خرید کن","خرید کردن با فهرست به صرفه‌جویی کمک می‌کند.","Kharid kardan bā fehrest be sarfejuyi komak mikonad.","Shopping with a list helps save money.","این کالا را خرید کن.","In kālā rā kharid kon.","Compare prices before shopping.");
 N(20,"FA2-20","مو را از ماست کشیدن","mu rā az māst keshidan","to split hairs; be excessively exacting","اصطلاح — idiom","او آن‌قدر مو را از ماست می‌کشد که تصمیم‌گیری دشوار می‌شود.","U ān-qadr mu rā az māst mikeshad ke tasmim-giri doshvār mishavad.","He is so nit-picky that making a decision becomes difficult.");
 V(20,"FA2-20","قرض گرفتن","qarz gereftan","to borrow","قرض گرفتن","قرض بگیر","قرض گرفتن بدون برنامه می‌تواند مشکل ایجاد کند.","Qarz gereftan bedun-e barnāme mitavānad moshkel ijād konad.","Borrowing without a plan can create problems.","اگر لازم است، فقط به اندازهٔ نیاز قرض بگیر.","Agar lāzem ast, faqat be andāze-ye niyāz qarz begir.","If necessary, borrow only what you need.");
 V(3,"KH2-03","مخفی شدن","makhfi shodan","to hide","مخفی شدن","مخفی شو","مخفی شدن کودک در بازی باعث خنده شد.","Makhfi shodan-e kudak dar bāzi bā'es-e khande shod.","The child's hiding during the game caused laughter.","برای بازی پشت در مخفی شو.","Barāye bāzi posht-e dar makhfi sho.","Hide behind the door for the game.");
 V(10,"KH2-10","گره زدن","gereh zadan","to tie a knot","گره زدن","گره بزن","گره زدن نخ در بافت فرش مهارت می‌خواهد.","Gereh zadan-e nakh dar bāft-e farsh mahārat mikhāhad.","Tying yarn knots in carpet weaving requires skill.","نخ را محکم گره بزن.","Nakh rā mohkam gereh bezan.","Tie the yarn firmly.");
 V(18,"KH2-18","در ذهن ماندن","dar zehn māndan","to remain in memory","در ذهن ماندن","در ذهن بمان","در ذهن ماندن نکته‌های مهم به مرور نیاز دارد.","Dar zehn māndan-e nokte-hā-ye mohem be morur niyāz dārad.","Important points need review to remain in memory.","این نکته را بخوان تا در ذهن بمان.","In nokte rā bekhān tā dar zehn bemān.","Read this point so it remains in your memory.");
 V(1,"SH2-01","تشریف آوردن","tashrif āvardan","to come (honorific)","تشریف آوردن","تشریف بیاورید","تشریف آوردن مهمانان باعث خوشحالی میزبان شد.","Tashrif āvardan-e mehmānān bā'es-e khoshhāli-ye mizbān shod.","The guests' arrival made the host happy.","لطفاً فردا به جلسه تشریف بیاورید.","Lotfan fardā be jalase tashrif biyāvarid.","Please come to the meeting tomorrow.");
 V(8,"SH2-08","کنسل شدن","konsel shodan","to be cancelled","کنسل شدن","—","کنسل شدن پرواز به دلیل طوفان مسافران را نگران کرد.","Konsel shodan-e parvāz be dalil-e tufān mosāferān rā negarān kard.","The cancellation of the flight due to the storm worried passengers.","","","","این فعل لازم/مجهول است و فرمان مستقیم طبیعی ندارد؛ امر مستقیم برای آن ثبت نشده است.");
