 N(11,"FA2-11","دوچرخه‌سواری","docharkhe-savāri","cycling","اسم — noun","دوچرخه‌سواری از فعالیت‌های موردعلاقهٔ اوست.","Docharkhe-savāri az fa'āliyat-hā-ye mored-e alāqe-ye u-st.","Cycling is one of his favourite activities.");
 N(11,"KH2-11","کم‌رویی","kam-ruyi","shyness","اسم — noun","کم‌رویی کودک با تشویق کمتر می‌شود.","Kam-ruyi-ye kudak bā tashviq kamtar mishavad.","A child's shyness can lessen with encouragement.");
 N(11,"FA2-11","گذشتهٔ استمراری","gozashte-ye estemrāri","past continuous tense","گروه اسمی — grammar term","گذشتهٔ استمراری برای کار ادامه‌دار در گذشته است.","Gozashte-ye estemrāri barāye kār-e edāme-dār dar gozashte ast.","The past continuous describes an ongoing past action.");
 N(12,"FA2-12","شمارهٔ پرواز","shomāre-ye parvāz","flight number","گروه اسمی — noun phrase","شمارهٔ پرواز روی کارت پرواز نوشته شده است.","Shomāre-ye parvāz ru-ye kārt-e parvāz neveshte shode ast.","The flight number is written on the boarding pass.");
 N(13,"FA2-13","خط عابر پیاده","khat-e āber-e piyāde","pedestrian crossing","گروه اسمی — noun phrase","راننده پیش از خط عابر پیاده توقف کرد.","Rānande pish az khat-e āber-e piyāde tavaqqof kard.","The driver stopped before the pedestrian crossing.");
 N(13,"FA2-13","ماضی استمراری","māzi-ye estemrāri","past continuous tense","گروه اسمی — grammar term","ماضی استمراری برای توصیف کار در جریان گذشته است.","Māzi-ye estemrāri barāye towsif-e kār dar jaryān-e gozashte ast.","The past continuous describes an action in progress in the past.");
 N(14,"FA2-14","در بین راه","dar beyn-e rāh","on the way","عبارت — expression","در بین راه خودرو خراب شد.","Dar beyn-e rāh khodro kharāb shod.","The car broke down on the way.");
 N(14,"FA2-14","ماضی بعید","māzi-ye ba'id","past perfect tense","گروه اسمی — grammar term","ماضی بعید کاری را نشان می‌دهد که پیش‌تر انجام شده بود.","Māzi-ye ba'id kāri rā neshān midahad ke pish-tar anjām shode bud.","The past perfect shows an action completed earlier.");
 N(15,"N2-08","آماده‌سازی","āmāde-sāzi","preparation","اسم — noun","آماده‌سازی مواد پیش از پخت زمان می‌برد.","Āmāde-sāzi-ye mavādd pish az pokht zamān mibарад.","Preparing ingredients before cooking takes time.",[15,16]);
 N(16,"SH2-01","به روی چشم","be ru-ye chashm","certainly; gladly (polite response)","عبارت گفتاری — spoken expression","پیشخدمت گفت: به روی چشم.","Pishkhedmat goft: be ru-ye chashm.","The server replied, “Certainly.”");
 N(16,"KH2-16","پاکیزگی","pākizegi","cleanliness","اسم — noun","پاکیزگی رستوران برای مشتریان مهم است.","Pākizegi-ye resturān barāye moshtariyān mohem ast.","Restaurant cleanliness matters to customers.");
 N(17,"FA2-17","رزرو اتاق","rezerv-e otāq","room reservation","گروه اسمی — noun phrase","رزرو اتاق را پیش از سفر تأیید کنید.","Rezerv-e otāq rā pish az safar ta'yid konid.","Confirm the room reservation before travelling.");
 N(18,"FA2-18","فوق‌لیسانس","foq-lisāns","master's degree","اسم — noun","او مدرک فوق‌لیسانس دارد.","U madrak-e foq-lisāns dārad.","He has a master's degree.");
 N(18,"FA2-18","روان‌شناسی","ravān-shenāsi","psychology","اسم — noun","روان‌شناسی رفتار انسان را بررسی می‌کند.","Ravān-shenāsi raftār-e ensān rā barrasi mikonad.","Psychology studies human behaviour.");
 N(19,"FA2-19","تعویض","ta'viz","exchange; replacement","اسم — noun","تعویض کالای خراب باید طبق مقررات انجام شود.","Ta'viz-e kālā-ye kharāb bāyad tebeq-e moqarrarāt anjām shavad.","Replacing a faulty product should follow the rules.");
 N(20,"FA2-20","اصطلاح","estelāh","expression; idiom","اسم — noun","این اصطلاح در گفتگوی روزمره کاربرد دارد.","In estelāh dar goftogu-ye ruzmare kārbord dārad.","This expression is used in everyday conversation.");
 N(20,"FA2-20","مضارع مستمر","mozāre'-e mostamer","present continuous tense","گروه اسمی — grammar term","مضارع مستمر کاری را نشان می‌دهد که اکنون ادامه دارد.","Mozāre'-e mostamer kāri rā neshān midahad ke aknun edāme dārad.","The present continuous describes an action happening now.");
 V(6,"FA2-06","بستری شدن","bastari shodan","to be hospitalised","بستری شدن","بستری شو","بستری شدن بیمار برای درمان لازم شد.","Bastari shodan-e bimār barāye darmān lāzem shod.","The patient needed to be hospitalised for treatment.","اگر لازم است، بستری شو.","Agar lāzem ast, bastari sho.","If necessary, be admitted to hospital.");
 V(1,"FA2-01","عفو کردن","afw kardan","to forgive","عفو کردن","عفو کن","عفو کردن دیگران نشانهٔ بزرگواری است.","Afw kardan-e digarān neshāne-ye bozorgvāri ast.","Forgiving others is a sign of generosity.","اشتباه دوستت را عفو کن.","Eshtebāh-e dustat rā afw kon.","Forgive your friend's mistake.");
 V(1,"FA2-01","دست تکان دادن","dast takān dādan","to wave (one's hand)","دست تکان دادن","دست تکان بده","دست تکان دادن از دور نوعی سلام است.","Dast takān dādan az dur now'i salām ast.","Waving from a distance is a kind of greeting.","برای خداحافظی دست تکان بده.","Barāye khodāhāfezi dast takān bedeh.","Wave goodbye.");
 V(2,"FA2-02","دروغ گفتن","dorugh goftan","to lie","دروغ گفتن","دروغ نگو","دروغ گفتن اعتماد را از بین می‌برد.","Dorugh goftan e'temād rā az beyn mibорад.","Lying destroys trust.","به دوستت دروغ نگو.","Be dustat dorugh nagu.","Do not lie to your friend.");
 V(2,"FA2-02","جمع زدن","jam' zadan","to add up; calculate a total","جمع زدن","جمع بزن","جمع زدن هزینه‌ها پیش از خرید مفید است.","Jam' zadan-e hazine-hā pish az kharid mofid ast.","Adding up the costs before shopping is useful.","قیمت‌ها را جمع بزن.","Gheymat-hā rā jam' bezan.","Add up the prices.");
 V(3,"FA2-03","انجام دادن","anjām dādan","to do; carry out","انجام دادن","انجام بده","انجام دادن تمرین‌ها به یادگیری کمک می‌کند.","Anjām dādan-e tamrin-hā be yādgiri komak mikonad.","Doing the exercises helps learning.","تمرین را کامل انجام بده.","Tamrin rā kāmel anjām bedeh.","Complete the exercise.");
 V(4,"FA2-04","بازداشت شدن","bāzdāsht shodan","to be arrested","بازداشت شدن","—","بازداشت شدن متهم پس از بررسی شواهد انجام شد.","Bāzdāsht shodan-e moteham pas az barrasi-ye shavāhed anjām shod.","The suspect was arrested after the evidence was examined.","","","","این فعل مجهول است و فرمان مستقیم طبیعی ندارد؛ امر مستقیم ثبت نشده است.");
 V(4,"FA2-04","ناراحت شدن","nārāhat shodan","to become upset","ناراحت شدن","ناراحت نشو","ناراحت شدن او از خبر ناگهانی قابل فهم بود.","Nārāhat shodan-e u az khabar-e nāgahāni ghābel-e fahm bud.","It was understandable that the sudden news upset him.","از یک اشتباه کوچک ناراحت نشو.","Az yek eshtebāh-e kuchak nārāhat nasho.","Do not get upset over a small mistake.");
 V(5,"FA2-05","حرکت دادن","harekat dādan","to move; make something move","حرکت دادن","حرکت بده","حرکت دادن دست آسیب‌دیده ممکن است دردناک باشد.","Harekat dādan-e dast-e āsib-dide momken ast dardnāk bāshad.","Moving an injured hand may be painful.","آرام دستت را حرکت بده.","Ārām dastat rā harekat bedeh.","Move your hand gently.");
 V(5,"FA2-05","تصادف کردن","tasādof kardan","to have an accident","تصادف کردن","—","تصادف کردن در جادهٔ لغزنده خطرناک است.","Tasādof kardan dar jāde-ye laghzande khatarnāk ast.","Having an accident on a slippery road is dangerous.","","","","این فعل رویدادی ناخواسته را بیان می‌کند و فرمان مستقیم طبیعی ندارد.");
 V(6,"FA2-06","مرخص شدن","morakhkhas shodan","to be discharged (from hospital)","مرخص شدن","مرخص شو","مرخص شدن بیمار پس از بهبود انجام شد.","Morakhkhas shodan-e bimār pas az behbud anjām shod.","The patient was discharged after recovery.","اگر پزشک اجازه داد، مرخص شو.","Agar pezeshk ejāze dād, morakhkhas sho.","Leave the hospital if the doctor permits.");
 V(6,"FA2-06","مشورت کردن","mashverat kardan","to consult; seek advice","مشورت کردن","مشورت کن","مشورت کردن با پزشک پیش از درمان مهم است.","Mashverat kardan bā pezeshk pish az darmān mohem ast.","Consulting a doctor before treatment is important.","پیش از تصمیم‌گیری مشورت کن.","Pish az tasmim-giri mashverat kon.","Seek advice before deciding.");
 V(7,"FA2-07","آواره شدن","āvāre shodan","to become displaced","آواره شدن","—","آواره شدن خانواده‌ها پس از سیل بسیار دشوار بود.","Āvāre shodan-e khānevāde-hā pas az seyl besyār doshvār bud.","Families becoming displaced after the flood was very difficult.","","","","این فعل حالت ناخواستهٔ افراد را بیان می‌کند و امر مستقیم طبیعی ندارد.");
 V(7,"FA2-07","بیرون آوردن","birun āvardan","to bring out; rescue","بیرون آوردن","بیرون بیاور","بیرون آوردن افراد از زیر آوار به کمک امدادگران نیاز دارد.","Birun āvardan-e afrād az zir-e āvār be komak-e emdādgarān niyāz dārad.","Rescuing people from rubble requires emergency workers.","افراد را با احتیاط بیرون بیاور.","Afrād rā bā ehtiyāt birun biyāvar.","Bring the people out carefully.");
 V(8,"FA2-08","سفر کردن","safar kardan","to travel","سفر کردن","سفر کن","سفر کردن به شهرهای تاریخی تجربهٔ آموزنده‌ای است.","Safar kardan be shahr-hā-ye tārikhi tajrobe-ye āmuzande-i ast.","Travelling to historic cities is educational.","با برنامه سفر کن.","Bā barnāme safar kon.","Travel with a plan.");
 V(8,"FA2-08","ضعیف شدن","za'if shodan","to become weak","ضعیف شدن","—","ضعیف شدن بدن پس از بی‌خوابی طبیعی است.","Za'if shodan-e badan pas az bi-khābi tabi'i ast.","The body becoming weak after sleeplessness is natural.","","","","این فعل تغییر حالت را بیان می‌کند و فرمان مستقیم طبیعی ندارد.");
 V(9,"FA2-09","تلویزیون دیدن","televizion didan","to watch television","تلویزیون دیدن","تلویزیون ببین","تلویزیون دیدن بیش از اندازه زمان مطالعه را کم می‌کند.","Televizion didan-e bish az andāze zamān-e motāle'e rā kam mikonad.","Watching too much television reduces study time.","امشب تلویزیون ببین.","Emshab televizion bebin.","Watch television tonight.");
 V(9,"FA2-09","تمام کردن","tamām kardan","to finish; complete","تمام کردن","تمام کن","تمام کردن فیلم‌نامه زمان زیادی برد.","Tamām kardan-e film-nāme zamān-e ziyādi bord.","Finishing the screenplay took a long time.","کارت را تا عصر تمام کن.","Kārat rā tā asr tamām kon.","Finish your work by evening.");
 V(10,"FA2-10","خریدن","kharidan","to buy","خریدن","بخر","خریدن یک اثر هنری به شناخت آن نیاز دارد.","Kharidan-e yek asar-e honari be shenākht-e ān niyāz dārad.","Buying a work of art requires understanding it.","اگر دوست داری، این تابلو را بخر.","Agar dust dāri, in tāblo rā bekhar.","If you like it, buy this painting.");
 V(11,"FA2-11","کار کردن","kār kardan","to work","کار کردن","کار کن","کار کردن در کودکی بخشی از خاطرهٔ او بود.","Kār kardan dar kudaki bakhshi az khātere-ye u bud.","Working as a child was part of his memory.","با دقت کار کن.","Bā deqqat kār kon.","Work carefully.");
 V(11,"FA2-11","مسواک زدن","mesvāk zadan","to brush one's teeth","مسواک زدن","مسواک بزن","مسواک زدن پیش از خواب عادت خوبی است.","Mesvāk zadan pish az khāb ādat-e khubi ast.","Brushing your teeth before sleep is a good habit.","هر شب مسواک بزن.","Har shab mesvāk bezan.","Brush your teeth every night.");
 V(12,"FA2-12","باز و بسته کردن","bāz-o-baste kardan","to open and close","باز و بسته کردن","باز و بسته کن","باز و بسته کردن درِ چمدان باید آسان باشد.","Bāz-o-baste kardan-e dar-e chamedān bāyad āsān bāshad.","Opening and closing the suitcase should be easy.","در را آرام باز و بسته کن.","Dar rā ārām bāz-o-baste kon.","Open and close the door gently.");
 V(12,"FA2-12","سوار شدن","savār shodan","to get on; board","سوار شدن","سوار شو","سوار شدن به هواپیما پس از اعلام گیت آغاز شد.","Savār shodan be havāpeymā pas az e'lām-e geit āghāz shod.","Boarding the plane began after the gate announcement.","پس از اعلام، سوار شو.","Pas az e'lām, savār sho.","Board after the announcement.");
 V(13,"FA2-13","پنچر شدن","pancher shodan","to get a flat tyre","پنچر شدن","—","پنچر شدن لاستیک در جاده سفر را متوقف کرد.","Pancher shodan-e lāstik dar jāde safar rā motevaqqef kard.","A flat tyre stopped the journey.","","","","این فعل تغییر ناخواستهٔ وضعیت را بیان می‌کند و فرمان مستقیم طبیعی ندارد.");
 V(13,"FA2-13","حرف زدن","harf zadan","to speak; talk","حرف زدن","حرف بزن","حرف زدن با تلفن هنگام رانندگی خطرناک است.","Harf zadan bā telefon hengām-e rāndegi khatarnāk ast.","Talking on the phone while driving is dangerous.","آرام و روشن حرف بزن.","Ārām o rowshan harf bezan.","Speak calmly and clearly.");
 V(14,"FA2-14","متوجه شدن","motevajjeh shodan","to realise; notice","متوجه شدن","متوجه شو","متوجه شدن اشتباه پیش از حرکت بهتر است.","Motevajjeh shodan-e eshtebāh pish az harekat behtar ast.","It is better to notice the mistake before departure.","به نشانه‌ها متوجه شو.","Be neshāne-hā motevajjeh sho.","Pay attention to the signs.");
 V(15,"FA2-15","اضافه کردن","ezāfe kardan","to add","اضافه کردن","اضافه کن","اضافه کردن سبزی به غذا طعم آن را تغییر می‌دهد.","Ezāfe kardan-e sabzi be ghazā ta'm-e ān rā taghyir midahad.","Adding vegetables changes the flavour of the food.","کمی نمک اضافه کن.","Kami namak ezāfe kon.","Add a little salt.");
 V(15,"FA2-15","خوردن","khordan","to eat","خوردن","بخور","خوردن غذای متعادل به سلامت کمک می‌کند.","Khordan-e ghazā-ye mota'ādel be salāmat komak mikonad.","Eating a balanced meal supports health.","میوهٔ تازه بخور.","Mive-ye tāze bekhor.","Eat fresh fruit.");
 V(16,"FA2-16","سبزی خوردن","sabzi khordan","to eat fresh herbs","سبزی خوردن","سبزی بخور","سبزی خوردن کنار غذا در بسیاری از خانواده‌ها رایج است.","Sabzi khordan kenār-e ghazā dar besyāri az khānevāde-hā rāyej ast.","Eating fresh herbs with a meal is common in many families.","کنار غذا سبزی بخور.","Kenār-e ghazā sabzi bekhor.","Eat fresh herbs with your meal.");
 V(17,"FA2-17","اتاق گرفتن","otāq gereftan","to get a room","اتاق گرفتن","اتاق بگیر","اتاق گرفتن در فصل سفر دشوارتر است.","Otāq gereftan dar fasl-e safar doshvār-tar ast.","Getting a room is harder during the travel season.","برای خانواده اتاق بگیر.","Barāye khānevāde otāq begir.","Get a room for the family.");
 V(17,"FA2-17","دیدن","didan","to see; visit","دیدن","ببین","دیدن امکانات هتل پیش از رزرو مفید است.","Didan-e emkānāt-e hotel pish az rezerv mofid ast.","It is useful to see the hotel facilities before booking.","اتاق را از نزدیک ببین.","Otāq rā az nazdik bebin.","See the room in person.");
 V(18,"FA2-18","درس خواندن","dars khāndan","to study","درس خواندن","درس بخوان","درس خواندن منظم به موفقیت کمک می‌کند.","Dars khāndan-e monazzam be movaffaqiyat komak mikonad.","Regular studying helps success.","هر روز درس بخوان.","Har ruz dars bekhān.","Study every day.");
 V(18,"FA2-18","کم کردن","kam kardan","to reduce; decrease","کم کردن","کم کن","کم کردن هزینه‌ها به برنامه‌ریزی نیاز دارد.","Kam kardan-e hazine-hā be barnāme-rizi niyāz dārad.","Reducing expenses requires planning.","هزینه‌های اضافی را کم کن.","Hazine-hā-ye ezāfi rā kam kon.","Reduce unnecessary expenses.");
 V(19,"FA2-19","عطر زدن","atr zadan","to apply perfume","عطر زدن","عطر بزن","عطر زدن پیش از مهمانی برای بعضی افراد عادت است.","Atr zadan pish az mehmani barāye ba'zi afrād ādat ast.","Applying perfume before a gathering is a habit for some people.","مقدار کمی عطر بزن.","Meqdār-e kami atr bezan.","Apply a little perfume.");
 V(20,"FA2-20","ترک کردن","tark kardan","to quit; leave","ترک کردن","ترک کن","ترک کردن عادت بد به اراده نیاز دارد.","Tark kardan-e ādat-e bad be erāde niyāz dārad.","Quitting a bad habit requires willpower.","این عادت را ترک کن.","In ādat rā tark kon.","Quit this habit.");
 V(20,"FA2-20","دعوت کردن","da'vat kardan","to invite","دعوت کردن","دعوت کن","دعوت کردن دوستان به مهمانی رسم خوبی است.","Da'vat kardan-e dustān be mehmani rasm-e khubi ast.","Inviting friends to a gathering is a nice custom.","دوستت را به مهمانی دعوت کن.","Dustat rā be mehmani da'vat kon.","Invite your friend to the gathering.");
 V(1,"KH2-01","ارتباط برقرار کردن","ertebāt barqarār kardan","to communicate; establish contact","ارتباط برقرار کردن","ارتباط برقرار کن","ارتباط برقرار کردن با دیگران به شنیدن نیاز دارد.","Ertebāt barqarār kardan bā digarān be shenidan niyāz dārad.","Communicating with others requires listening.","با همکلاسی‌ها ارتباط برقرار کن.","Bā hamkelāsi-hā ertebāt barqarār kon.","Communicate with your classmates.");
 V(1,"KH2-01","هدیه دادن","hediye dādan","to give a gift","هدیه دادن","هدیه بده","هدیه دادن نشانهٔ محبت است.","Hediye dādan neshāne-ye mohabbat ast.","Giving a gift is a sign of affection.","به دوستت هدیه بده.","Be dustat hediye bedeh.","Give your friend a gift.");
 V(2,"KH2-02","اختراع کردن","ekht rā' kardan","to invent","اختراع کردن","اختراع کن","اختراع کردن تلفن همراه ارتباط را آسان کرد.","Ekht rā' kardan-e telefon-e hamrāh ertebāt rā āsān kard.","Inventing the mobile phone made communication easier.","برای حل مسئله راه تازه‌ای اختراع کن.","Barāye hal-e mas'ale rāh-e tāze-i ekht rā' kon.","Invent a new way to solve the problem.");
 V(2,"KH2-02","صدمه زدن","sadme zadan","to harm; injure","صدمه زدن","صدمه نزن","صدمه زدن به دیگران رفتار درستی نیست.","Sadme zadan be digarān raftār-e dorosti nist.","Harming others is not right.","به خودت و دیگران صدمه نزن.","Be khodet o digarān sadme nazan.","Do not harm yourself or others.");
 V(3,"KH2-03","پنهان شدن","penhān shodan","to hide","پنهان شدن","پنهان شو","پنهان شدن پشت در بخشی از بازی بود.","Penhān shodan posht-e dar bakhshi az bāzi bud.","Hiding behind the door was part of the game.","برای بازی پنهان شو.","Barāye bāzi penhān sho.","Hide for the game.");
 V(3,"KH2-03","فرار کردن","farār kardan","to run away; escape","فرار کردن","فرار کن","فرار کردن بازیکن از میدان باعث پایان بازی شد.","Farār kardan-e bāzikon az meydān bā'es-e pāyān-e bāzi shod.","The player's escape from the field ended the game.","از خطر فرار کن.","Az khatar farār kon.","Run away from danger.");
 V(3,"KH2-03","تصمیم گرفتن","tasmim gereftan","to decide","تصمیم گرفتن","تصمیم بگیر","تصمیم گرفتن دربارهٔ بازی به گروه واگذار شد.","Tasmim gereftan darbāre-ye bāzi be goruh vagozār shod.","The group was left to decide about the game.","با دقت تصمیم بگیر.","Bā deqqat tasmim begir.","Decide carefully.");
 V(4,"KH2-04","ارسال کردن","ersāl kardan","to send; transmit","ارسال کردن","ارسال کن","ارسال کردن تصویر بدون اجازه درست نیست.","Ersāl kardan-e tasvir bedun-e ejāze dorost nist.","Sending an image without permission is not right.","پیام را برای گروه ارسال کن.","Payām rā barāye goruh ersāl kon.","Send the message to the group.");
 V(4,"KH2-04","احترام گذاشتن","ehterām gozāshtan","to respect","احترام گذاشتن","احترام بگذار","احترام گذاشتن به حریم خصوصی ضروری است.","Ehterām gozāshtan be harim-e khosusi zaruri ast.","Respecting privacy is essential.","به نظر دیگران احترام بگذار.","Be nazar-e digarān ehterām bogozār.","Respect other people's opinions.");
 V(5,"KH2-05","خم شدن","kham shodan","to bend; stoop","خم شدن","خم شو","خم شدن از زانو هنگام برداشتن وسیله بهتر است.","Kham shodan az zānu hengām-e bardāshtan-e vasile behtar ast.","Bending at the knees when lifting something is better.","برای برداشتن جعبه کمی خم شو.","Barāye bardāshtan-e ja'be kami kham sho.","Bend a little to lift the box.");
 V(5,"KH2-05","تمیز کردن","tamiz kardan","to clean","تمیز کردن","تمیز کن","تمیز کردن خانه میان اعضای خانواده تقسیم شد.","Tamiz kardan-e khāne miyān-e a'zā-ye khānevāde taqsim shod.","Cleaning the house was divided among family members.","میز را تمیز کن.","Miz rā tamiz kon.","Clean the table.");
 V(5,"KH2-05","جارو کردن","jāru kardan","to sweep","جارو کردن","جارو کن","جارو کردن اتاق بخشی از کارهای خانه است.","Jāru kardan-e otāq bakhshi az kār-hā-ye khāne ast.","Sweeping the room is part of housework.","اتاق را جارو کن.","Otāq rā jāru kon.","Sweep the room.");
 V(6,"KH2-06","خوشامد گفتن","khoshāmad goftan","to welcome","خوشامد گفتن","خوشامد بگو","خوشامد گفتن به بیمار رفتار پسندیده‌ای است.","Khoshāmad goftan be bimār raftār-e pasandidе-i ast.","Welcoming a patient is a kind gesture.","به مهمانان خوشامد بگو.","Be mehmānān khoshāmad begu.","Welcome the guests.");
 V(7,"KH2-07","سقوط کردن","soqut kardan","to fall; crash","سقوط کردن","—","سقوط کردن هواپیما خسارت زیادی به بار آورد.","Soqut kardan-e havāpeymā khasārat-e ziyādi be bār āvard.","The plane crash caused great damage.","","","","این فعل رویداد ناخواسته را بیان می‌کند و فرمان مستقیم طبیعی ندارد.");
 V(7,"KH2-07","غرق شدن","qarq shodan","to drown; sink","غرق شدن","—","غرق شدن کشتی در طوفان مسافران را به خطر انداخت.","Qarq shodan-e keshti dar tufān mosāferān rā be khatar اندākht.","The ship sinking in the storm endangered passengers.","","","","این فعل حالت ناخواسته را بیان می‌کند و فرمان مستقیم طبیعی ندارد.");
 V(8,"KH2-08","نشان دادن","neshān dādan","to show","نشان دادن","نشان بده","نشان دادن مسیر به گردشگران کمک کرد.","Neshān dādan-e masir be gardeshgarān komak kard.","Showing the route helped the tourists.","نقشه را به من نشان بده.","Naqshe rā be man neshān bedeh.","Show me the map.");
 V(8,"KH2-08","دعوت کردن","da'vat kardan","to invite","دعوت کردن","دعوت کن","دعوت کردن مهمانان برای شام رسم خوبی است.","Da'vat kardan-e mehmānān barāye shām rasm-e khubi ast.","Inviting guests for dinner is a nice custom.","دوستت را دعوت کن.","Dustat rā da'vat kon.","Invite your friend.");
 V(10,"KH2-10","خشک کردن","khoshk kardan","to dry","خشک کردن","خشک کن","خشک کردن فرش پس از شست‌وشو زمان می‌برد.","Khoshk kardan-e farsh pas az shost-o-shu zamān mibарад.","Drying a carpet after washing takes time.","دست‌هایت را خشک کن.","Dast-hāyat rā khoshk kon.","Dry your hands.");
 V(11,"KH2-11","سریع خواندن","sari' khāndan","to read quickly","سریع خواندن","سریع بخوان","سریع خواندن برای پیدا کردن نکتهٔ اصلی مفید است.","Sari' khāndan barāye peydā kardan-e nokte-ye asli mofid ast.","Reading quickly is useful for finding the main point.","متن را سریع بخوان.","Matn rā sari' bekhān.","Read the text quickly.");
 V(11,"KH2-11","نگاه کردن","negāh kardan","to look; watch","نگاه کردن","نگاه کن","نگاه کردن به تصویر به فهم داستان کمک می‌کند.","Negāh kardan be tasvir be fahm-e dāstān komak mikonad.","Looking at the picture helps understand the story.","به تصویر نگاه کن.","Be tasvir negāh kon.","Look at the picture.");
 V(12,"KH2-12","خلاصه کردن","kholāse kardan","to summarise","خلاصه کردن","خلاصه کن","خلاصه کردن خبر به انتخاب نکته‌های اصلی نیاز دارد.","Kholāse kardan-e khabar be entekhāb-e nokte-hā-ye asli niyāz dārad.","Summarising the news requires selecting the main points.","داستان را در پنج جمله خلاصه کن.","Dāstān rā dar panj jomle kholāse kon.","Summarise the story in five sentences.");
 V(15,"KH2-15","آماده کردن","āmāde kardan","to prepare","آماده کردن","آماده کن","آماده کردن مواد اولیه پیش از آشپزی زمان را ذخیره می‌کند.","Āmāde kardan-e mavādd-e avvaliye pish az āshpazi zamān rā ذخیره mikonad.","Preparing ingredients before cooking saves time.","مواد لازم را آماده کن.","Mavādd-e lāzem rā āmāde kon.","Prepare the required ingredients.");
 V(15,"KH2-15","درست کردن","dorost kardan","to make; prepare","درست کردن","درست کن","درست کردن غذا با دستور روشن آسان‌تر است.","Dorost kardan-e ghazā bā dastur-e rowshan āsāntar ast.","Preparing food is easier with clear instructions.","این غذا را درست کن.","In ghazā rā dorost kon.","Make this dish.");
 V(17,"KH2-17","سکونت کردن","sokunat kardan","to reside; stay","سکونت کردن","سکونت کن","سکونت کردن در هتل برای چند شب هزینه دارد.","Sokunat kardan dar hotel barāye chand shab hazine dārad.","Staying in a hotel for several nights costs money.","در این هتل سکونت کن.","Dar in hotel sokunat kon.","Stay at this hotel.");
 V(18,"KH2-18","یادداشت کردن","yāddāsht kardan","to take notes; note down","یادداشت کردن","یادداشت کن","یادداشت کردن نکته‌ها به مرور کمک می‌کند.","Yāddāsht kardan-e nokte-hā be morur komak mikonad.","Taking notes helps with review.","نکته‌های مهم را یادداشت کن.","Nokte-hā-ye mohem rā yāddāsht kon.","Write down the important points.");
 V(18,"KH2-18","تکرار کردن","tekrār kardan","to repeat","تکرار کردن","تکرار کن","تکرار کردن واژه‌ها به یادگیری کمک می‌کند.","Tekrār kardan-e vāzhe-hā be yādgiri komak mikonad.","Repeating words helps learning.","این جمله را تکرار کن.","In jomle rā tekrār kon.","Repeat this sentence.");
 V(19,"KH2-19","مقاومت کردن","moqāvemat kardan","to resist","مقاومت کردن","مقاومت کن","مقاومت کردن در برابر فشار نادرست گاهی لازم است.","Moqāvemat kardan dar barābar-e فشار-e nādorost gāhi lāzem ast.","Resisting improper pressure is sometimes necessary.","در برابر وسوسه مقاومت کن.","Dar barābar-e vasvase moqāvemat kon.","Resist the temptation.");
 V(19,"KH2-19","اشتباه کردن","eshtebāh kardan","to make a mistake","اشتباه کردن","اشتباه نکن","اشتباه کردن بخشی از فرایند یادگیری است.","Eshtebāh kardan bakhshi az farāyand-e yādgiri ast.","Making mistakes is part of learning.","در محاسبه اشتباه نکن.","Dar mohāsebe eshtebāh nakon.","Do not make a mistake in the calculation.");
 V(20,"KH2-20","مجبور شدن","majbur shodan","to be forced; have to","مجبور شدن","—","مجبور شدن به ترک خانه برای خانواده دشوار بود.","Majbur shodan be tark-e khāne barāye khānevāde doshvār bud.","Being forced to leave home was difficult for the family.","","","","این فعل حالت ناخواسته را بیان می‌کند و فرمان مستقیم طبیعی ندارد.");
 V(20,"KH2-20","لبخند زدن","labkhand zadan","to smile","لبخند زدن","لبخند بزن","لبخند زدن فضای گفتگو را دوستانه می‌کند.","Labkhand zadan fazā-ye goftogu rā dustāne mikonad.","Smiling makes a conversation friendlier.","به مهمان لبخند بزن.","Be mehmān labkhand bezan.","Smile at the guest.");
 V(20,"KH2-20","خبر دادن","khabar dādan","to inform; notify","خبر دادن","خبر بده","خبر دادن به خانواده پس از رسیدن مهم است.","Khabar dādan be khānevāde pas az residan mohem ast.","It is important to inform the family after arriving.","پس از رسیدن خبر بده.","Pas az residan khabar bedeh.","Let us know after you arrive.");
